import {calendarToday,lateDays} from './lifecycle.js';
export function createLifecycleUI(c){
 const {esc,date,openModal}=c,s=()=>c.state();
 const acceptanceLabels={awaiting:'Ожидает приёмки',changes:'Нужны исправления',accepted:'Принято заказчиком'};
 const eventLabels={proposed:'Сроки предложены',approved:'Сроки согласованы',rejected:'Сроки отклонены',submitted:'Работы сданы на приёмку',accepted:'Принято заказчиком',changes:'Нужны исправления'};
 const find=(scope,id)=>scope==='project'?s().projects.find(p=>p.id===id):s().estimates.find(e=>e.id===id);
 const attrs=(scope,t)=>`data-scope="${scope}" data-id="${t.id}"`;
 function panel(scope,t,readOnly=false){
  if(!t||(scope==='estimate'&&t.status!=='approved'))return '';
  const p=scope==='project'?t:s().projects.find(p=>p.id===t.projectId),sch=t.schedule||{},a=t.acceptance,days=a?.status==='accepted'?0:lateDays(sch.end),contractor=s().user.id===p.contractorId,client=s().user.id===p.clientId,active=!p.completedAt&&!readOnly,accepted=a?.status==='accepted';
  return `<section class="panel lifecycle-panel"><div class="panel-head"><h2>${scope==='project'?'Основные работы: сроки и приёмка':'Сроки и приёмка допработ'}</h2>${a?`<span class="badge ${accepted?'approved':a.status==='changes'?'rejected':'pending'}">${acceptanceLabels[a.status]}</span>`:''}</div><div class="panel-body"><h3>Согласованные сроки</h3>${sch.end?`<p><strong>${esc(sch.start)} → ${esc(sch.end)}</strong></p>`:'<p class="muted">Сроки ещё не согласованы</p>'}${days?`<p class="notice warning">Просрочка по согласованному сроку: <strong>${days}</strong> <span>дн.</span></p>`:''}<small>Календарные дни · время Казахстана (UTC+5)</small>${sch.pending?`<div class="notice warning"><strong>Предложены новые даты</strong><p>${esc(sch.pending.start)} → ${esc(sch.pending.end)}</p><p>${esc(sch.pending.reason)}</p><small>Текущие сроки действуют до решения заказчика.</small>${active&&client?`<div class="actions"><button class="btn primary" data-act="life-schedule-approve" ${attrs(scope,t)}>Согласовать даты</button><button class="btn" data-act="life-schedule-reject" ${attrs(scope,t)}>Отклонить даты</button></div>`:''}</div>`:''}${active&&contractor&&!['awaiting','accepted'].includes(a?.status)?`<p><button class="btn" data-act="life-schedule" ${attrs(scope,t)}>${sch.end?'Предложить перенос':'Предложить сроки'}</button></p>`:''}<details><summary>История сроков</summary>${(sch.history||[]).map(h=>`<p><strong>${eventLabels[h.event]}</strong> · ${esc(h.start)} → ${esc(h.end)}<br>${esc(h.reason)} ${esc(h.decisionReason||'')}<br><small>${esc(h.actor)} · ${date(h.at)}</small></p>`).join('')||'<p>Изменений пока нет.</p>'}</details><hr><h3>Приёмка заказчиком</h3>${scope==='project'?`<p class="muted">Ход основных работ: ${({not_started:'Не начато',in_progress:'В работе',done:'Завершено'})[t.execution?.status]||'Не начато'}</p>`:''}${active&&contractor&&scope==='project'&&!['awaiting','accepted'].includes(a?.status)?`<button class="btn small" data-act="life-work" ${attrs(scope,t)}>Начать / продолжить работы</button>`:''}${a?`<div class="notice ${a.status==='changes'?'warning':''}"><strong>${acceptanceLabels[a.status]}</strong><p>${esc(a.report)}</p>${a.reason?`<p><strong>Замечания заказчика:</strong> ${esc(a.reason)}</p>`:''}</div>`:'<p class="muted">Работы ещё не сданы на приёмку.</p>'}${active&&contractor&&!['awaiting','accepted'].includes(a?.status)?`<p><button class="btn primary" data-act="life-submit" ${attrs(scope,t)}>${a?.status==='changes'?'Сдать повторно после исправлений':'Сдать работы на приёмку'}</button></p>`:''}${active&&client&&a?.status==='awaiting'?`<div class="actions"><button class="btn primary" data-act="life-accept" ${attrs(scope,t)}>Принять работы</button><button class="btn" data-act="life-changes" ${attrs(scope,t)}>Запросить исправления</button></div>`:''}<p class="muted">Приёмка фиксирует решение заказчика о результате работ. Она не подтверждает оплату и не меняет бюджет.</p><details><summary>История приёмки</summary>${(t.acceptanceHistory||[]).map(h=>`<p><strong>${eventLabels[h.event]}</strong><br>${esc(h.report)} ${esc(h.reason||'')}<br><small>${esc(h.actor)} · ${date(h.at)}</small></p>`).join('')||'<p>Изменений пока нет.</p>'}</details></div></section>`;
 }

 function chatAllowed(p){return p&&['client','contractor'].includes(s().user.role)&&[p.clientId,p.contractorId].includes(s().user.id);}
 function messagesHTML(p){const rows=(s().messages||[]).filter(m=>m.projectId===p.id);return rows.length?rows.map(m=>`<article class="chat-message ${m.senderId===s().user.id?'mine':''}"><div><strong>${esc(m.sender)}</strong><small>${date(m.at)}</small></div><p>${esc(m.text)}</p></article>`).join(''):'<p class="muted">Сообщений пока нет. Обсудите ремонт с участником проекта.</p>';}
 function chatPage(id){const p=s().projects.find(p=>p.id===id);if(!chatAllowed(p))return c.empty('Чат доступен только заказчику и подрядчику проекта');return `${c.heading('Чат проекта',esc(p.name),'<button class="btn" data-go="project" data-id="'+p.id+'">К проекту</button>')}<p class="notice">Переписку видят только заказчик и подрядчик этого проекта. Сообщение не утверждает смету, перенос сроков или приёмку — используйте соответствующие действия.</p><section class="panel"><div class="panel-head"><h2>Обсуждение ремонта</h2><button class="btn small" data-act="life-chat" data-id="${p.id}">Обновить чат</button></div><div id="project-messages" class="chat-messages" role="log" aria-label="Переписка проекта" aria-live="polite" data-project="${p.id}">${messagesHTML(p)}</div>${p.completedAt?'<p class="notice">Проект завершён. Переписка доступна только для чтения</p>':`<form id="project-chat-form" class="panel-body" data-project="${p.id}" data-nonce="${crypto.randomUUID()}"><label class="field">Ваше сообщение<textarea name="text" maxlength="2000" rows="3" required placeholder="Напишите о ремонте…"></textarea><small>До 2000 символов. Новые сообщения проверяются каждые 20 секунд.</small></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Отправить сообщение</button></form>`}</section>`;}
 function syncChat(){const box=document.querySelector('#project-messages');if(!box)return;const p=s().projects.find(p=>p.id===box.dataset.project);if(!chatAllowed(p))return;const bottom=box.scrollHeight-box.scrollTop-box.clientHeight<70,top=box.scrollTop;box.innerHTML=messagesHTML(p);box.scrollTop=bottom?box.scrollHeight:top;}
 document.addEventListener('submit',async event=>{const f=event.target;if(f.id!=='project-chat-form')return;event.preventDefault();const btn=f.querySelector('[type="submit"]');if(btn.disabled)return;btn.disabled=true;const error=f.querySelector('.form-error'),input=f.querySelector('textarea');error.textContent='';try{await c.action('chat.send',{projectId:f.dataset.project,text:input.value,clientMessageId:f.dataset.nonce});await c.refresh();input.value='';f.dataset.nonce=crypto.randomUUID();syncChat();input.focus();}catch(e){error.textContent=e.message;}finally{btn.disabled=false;}});

 function inbox(){const rows=s().notifications||[];return `${c.heading('Уведомления','События ваших заявок, проектов, сроков и приёмки.',`<button class="btn" data-act="life-read-all">Прочитать все</button>`)}<p class="notice">Уведомления внутри платформы. При открытом кабинете проверяем новые события каждые 20 секунд. Email и push не подключены.</p>${rows.length?rows.map(n=>`<article class="panel"><div class="panel-body"><span class="badge ${n.readAt?'draft':'pending'}">${n.readAt?'Прочитано':'Новое'}</span><h3>${esc(n.title)}</h3><p>${esc(n.context)}</p><small>${esc(n.actor)} · ${date(n.at)}</small><p><button class="btn small" data-act="life-open" data-id="${n.id}">Открыть событие</button></p></div></article>`).join(''):c.empty('Уведомлений пока нет.')}`;}
 function form(scope,t,action,title,body){openModal(title,`<form id="lifecycle-form" data-scope="${scope}" data-id="${t.id}" data-action="${action}" data-version="${action.startsWith('schedule')?t.scheduleVersion||0:t.acceptanceVersion||0}">${body}<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-act="modal-close">Отмена</button><button class="btn primary" type="submit">Подтвердить</button></div></form>`);}
 async function click(act,b){
  if(!act.startsWith('life-'))return false;
  if(act==='life-chat'){await c.action('chat.read',{projectId:b.dataset.id});await c.refresh();c.go('project-chat',{id:b.dataset.id});return true;}
  if(act==='life-read-all'){await c.action('notification.read',{all:true});await c.refresh();c.render();return true;}
  if(act==='life-open'){const n=s().notifications.find(n=>n.id===b.dataset.id);await c.action('notification.read',{id:n.id});if(n.chat)await c.action('chat.read',{projectId:n.projectId});await c.refresh();if(n.chat){c.go('project-chat',{id:n.projectId});return true;}c.go(n.estimateId?'estimate':n.projectId?'project':'requests',{id:n.estimateId||n.projectId});return true;}
  const scope=b.dataset.scope,t=find(scope,b.dataset.id);if(!t)throw Error('Работы недоступны');
  if(act==='life-schedule'){const sch=t.schedule||{},pending=sch.pending||{};form(scope,t,'schedule.propose',sch.end?'Предложить перенос':'Предложить сроки',`<p class="notice">Даты вступят в силу только после согласования заказчиком.</p><label class="field">Начало работ<input name="start" type="date" required value="${pending.start||sch.start||calendarToday()}"></label><label class="field">Окончание работ<input name="end" type="date" required value="${pending.end||sch.end||''}"></label><label class="field">Обоснование сроков / переноса<textarea name="reason" maxlength="2000" required>${esc(pending.reason||'')}</textarea></label>`);}
  if(act==='life-schedule-approve'||act==='life-schedule-reject'){form(scope,t,'schedule.decide',act==='life-schedule-approve'?'Согласовать даты':'Отклонить даты',`<input type="hidden" name="decision" value="${act==='life-schedule-approve'?'approved':'rejected'}"><p>${esc(t.schedule.pending.start)} → ${esc(t.schedule.pending.end)}</p>${act==='life-schedule-reject'?'<label class="field">Причина отклонения<textarea name="reason" maxlength="2000" required></textarea></label>':'<p>Эти даты станут согласованными сроками работ.</p>'}`);}
  if(act==='life-work'){await c.action('work.status',{scope,id:t.id,version:t.executionVersion||0,status:'in_progress'});await c.refresh();c.render();}
  if(act==='life-submit'){form(scope,t,'acceptance.submit','Сдать работы на приёмку','<p class="notice">Сначала согласуйте сроки. Опишите выполненный результат и исправления. Заказчик примет работы или вернёт замечания.</p><label class="field">Отчёт о выполнении<textarea name="report" required maxlength="2000"></textarea></label>');}
  if(act==='life-accept'||act==='life-changes'){form(scope,t,'acceptance.decide',act==='life-accept'?'Принять работы':'Запросить исправления',`<input type="hidden" name="decision" value="${act==='life-accept'?'accepted':'changes'}">${act==='life-accept'?'<p>Подтвердите, что вы проверили результат этих работ и принимаете его. Это не подтверждение оплаты.</p>':'<label class="field">Что нужно исправить?<textarea name="reason" required maxlength="2000"></textarea></label>'}`);}
  return true;
 }
 document.addEventListener('submit',async event=>{const f=event.target;if(f.id!=='lifecycle-form')return;event.preventDefault();const btn=f.querySelector('[type="submit"]');if(btn.disabled)return;btn.disabled=true;try{const d=Object.fromEntries(new FormData(f));await c.action(f.dataset.action,{...d,scope:f.dataset.scope,id:f.dataset.id,version:Number(f.dataset.version)});await c.refresh();c.closeModal();c.render();c.toast('Решение сохранено. Участники получат уведомление.');}catch(e){f.querySelector('.form-error').textContent=e.message;}finally{btn.disabled=false;}});
 return {panel,inbox,click,chatPage,syncChat};
}

